public void dibujarFila(int eq){
  float yf = yInicio + eq*alturaFila;

  //Franja de fondo
  noStroke();
  fill(franjaFondo);
  rect(0, yf+1, ancho, alturaFila-2);
  fill(franjaEstado);
  rect(0, yf+1, wEstado, alturaFila-2);

  //Círculo de conexión
  if(equipoConn[eq]){
    fill(verde);
  }
  else{
    fill(rojo);
  }
  ellipse(padEstado + diametroEstado*0.5f, yf + alturaFila*0.5f, diametroEstado, diametroEstado);

  //Nombre de la estación
  fill(azulFondo);
  textSize(tamTituloEstacion);
  textAlign(LEFT, CENTER);
  text("Estación " + nf(eq+1, 2, 0), xTituloEstado, yf + alturaFila*0.5f);

  //Sensores
  for(int col=0; col<5; col++){
    int si = gasSensor[col];
    float v = sensor[eq][si];
    float celdaX = xGauges + col*wGas;
    float cy = yf + alturaFila*0.5f;
    float rExt = alturaFila*0.40f;
    float rInt = rExt*0.60f;
    myVisorCompacto(v, gasMin[si], gasMax[si], gasColor[col], celdaX + wGas*0.16f, cy, rExt, rInt, celdaX + wGas*0.30f, cy, 1, gasDec[si], gasUnidad[si]);

    if(equipoConn[eq]){
      if(si == 4){
        alarmaO2Compacta(v, alarmaBaja[si], alarmaAlta[si], celdaX + 2, yf + 2, wGas - 4, alturaFila - 4);
      }
      else{
        alarmaCompacta(v, alarmaBaja[si], celdaX + 2, yf + 2, wGas - 4, alturaFila - 4);
      }
    }
  }
}

